session_start();require_once('dbstring.php');require_once('alumni-utils.php');alumni_ensure_tables($con);
$memberId=trim((string)($_SESSION['ALUMNI_MEMBER']??''));if($memberId===''){header('location:alumni-community.php');exit();}$stmt=mysqli_prepare($con,"SELECT alumniid,fullname FROM tblalumni WHERE alumniid=? AND status='active' LIMIT 1");mysqli_stmt_bind_param($stmt,'s',$memberId);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);$member=$result?mysqli_fetch_assoc($result):null;mysqli_stmt_close($stmt);if(!$member){unset($_SESSION['ALUMNI_MEMBER']);header('location:alumni-community.php');exit();}
$perPage=12;$page=max(1,(int)($_GET['page']??1));$search=trim((string)($_GET['q']??''));$where="status='active' AND directoryconsent=1";if($search!==''){$searchEsc=mysqli_real_escape_string($con,$search);$where.=" AND (fullname LIKE '%$searchEsc%' OR programme LIKE '%$searchEsc%' OR locationtext LIKE '%$searchEsc%' OR occupation LIKE '%$searchEsc%' OR CAST(graduationyear AS CHAR) LIKE '%$searchEsc%')";}$countResult=mysqli_query($con,"SELECT COUNT(*) total FROM tblalumni WHERE $where");$total=$countResult?(int)(mysqli_fetch_assoc($countResult)['total']??0):0;$pages=max(1,(int)ceil($total/$perPage));if($page>$pages)$page=$pages;$offset=($page-1)*$perPage;$directory=mysqli_query($con,"SELECT alumniid,fullname,graduationyear,programme,locationtext,occupation,profileimage,photoconsent FROM tblalumni WHERE $where ORDER BY graduationyear DESC,fullname ASC LIMIT $perPage OFFSET $offset");
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Private Alumni Directory | AYISEC</title><link rel="icon" type="image/png" href="logo/logo-transparent.png"><style>:root{--n:#102b4b;--t:#08766f;--g:#e3ac36;--p:#f4f7fb;--l:#dce5ed;--m:#64748b}*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#edf4f8,#f8fafc);color:#182b43;font:15px/1.55 Arial,sans-serif}.wrap{max-width:1120px;margin:auto;padding:38px 18px 65px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:end;padding:30px;border-radius:20px;background:linear-gradient(120deg,var(--n),#174e69 58%,var(--t));color:#fff}.hero small{color:#e7be61;font-weight:bold;letter-spacing:1.3px}.hero h1{font:600 32px Georgia,serif;margin:5px 0}.hero p{margin:0;color:#d9e6ec}.hero a{display:inline-block;margin-top:13px;padding:10px 13px;background:#fff;color:var(--n);border-radius:8px;text-decoration:none;font-weight:bold}.panel{margin-top:20px;padding:23px;border:1px solid var(--l);border-radius:16px;background:#fff;box-shadow:0 8px 20px #102b4b0d}.search{display:flex;gap:9px;margin-bottom:20px}.search input{flex:1;min-width:0;padding:12px;border:1px solid #c8d6e2;border-radius:9px;font:inherit}.search button,.clear{border:0;border-radius:9px;padding:12px 15px;background:var(--t);color:#fff;font-weight:bold;text-decoration:none;cursor:pointer}.clear{background:#e9f1f6;color:var(--n)}.count{margin:0 0 15px;color:var(--m);font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.person{display:flex;gap:12px;align-items:center;padding:15px;border:1px solid #e4ebf0;border-radius:12px;background:#fbfdff}.avatar{width:50px;height:50px;min-width:50px;border-radius:50%;object-fit:cover;background:linear-gradient(145deg,#d4ebe7,#e9eef8);border:2px solid #fff;box-shadow:0 3px 9px #102b4b1a}.person b,.person small{display:block}.person b{color:var(--n);font-size:14px}.person small{color:var(--m);font-size:12px;line-height:1.45;margin-top:3px}.pager{display:flex;justify-content:center;align-items:center;gap:11px;margin-top:22px}.pager a{padding:9px 12px;border-radius:8px;background:#edf6f5;color:var(--t);text-decoration:none;font-weight:bold;font-size:13px}.pager span{color:var(--m);font-size:13px;font-weight:bold}.empty{padding:30px;text-align:center;color:var(--m)}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.wrap{padding:22px 12px}.hero{align-items:flex-start;flex-direction:column;padding:23px}.hero h1{font-size:27px}.panel{padding:17px}.grid{grid-template-columns:1fr}.search{align-items:stretch;flex-direction:column}.search button,.clear{text-align:center}.pager{justify-content:space-between}}</style></head><body><main class="wrap"><section class="hero"><div><small>VERIFIED AYISEC ALUMNI ONLY</small><h1>Private Alumni Directory</h1><p>Reconnect with approved old students who chose to appear in the directory.</p><a href="alumni-community.php">← Back to community</a></div></section><section class="panel"><form class="search" method="get"><input name="q" value="<?php echo alumni_safe($search);?>" placeholder="Search by name, year, programme, location, or occupation"><button>Search</button><?php if($search!==''){?><a class="clear" href="alumni-private-directory.php">Clear</a><?php }?></form><p class="count"><?php echo number_format($total);?> member<?php echo $total===1?'':'s'; ?> found<?php echo $search!==''?' for “'.alumni_safe($search).'”':''; ?>.</p><?php if($directory&&mysqli_num_rows($directory)>0){?><div class="grid"><?php while($person=mysqli_fetch_assoc($directory)){?><article class="person"><?php if($person['photoconsent']&&$person['profileimage']){?><img class="avatar" src="alumni-photo.php?id=<?php echo rawurlencode($person['alumniid']);?>" alt=""><?php }else{?><span class="avatar"></span><?php }?><div><b><?php echo alumni_safe($person['fullname']);?></b><small><?php echo alumni_safe($person['graduationyear'].' · '.$person['programme']);?><br><?php echo alumni_safe($person['occupation'].' · '.$person['locationtext']);?></small></div></article><?php }?></div><?php }else{?><div class="empty">No verified Alumni directory profiles match this search.</div><?php }?><?php if($pages>1){?><nav class="pager"><?php if($page>1){?><a href="?page=<?php echo $page-1;?>&q=<?php echo rawurlencode($search);?>">← Previous</a><?php }?><span>Page <?php echo $page;?> of <?php echo $pages;?></span><?php if($page<$pages){?><a href="?page=<?php echo $page+1;?>&q=<?php echo rawurlencode($search);?>">Next →</a><?php }?></nav><?php }?></section></main></body></html>
